// divergences is what a node runs for each key where its own generated files and this binary's
// declaration disagree, per kind of node.
//
// A declared value is what the init command writes for a kind of node. That command is not the only thing
// in this binary that writes these files: a node started without them gets them generated by the boot
// instead, and the two do not agree. A third value comes from somewhere else again, because a key with a
// flag of its own on the start command is answered by that flag's default whether a file mentions it or
// not, and that default is stated where the flag is declared.
//
// Per kind of node, because the declaration varies on the kind and the writer does not. The boot's writer
// produces one shape for every kind, so a declaration for a kind that shape does not describe disagrees
// with it. Measuring one kind finds a quarter of the rows.
//
// Each row is a setting a sparse sei.toml moves, because a key that file leaves out takes the declared
// value. What the move does, by group:
//
//	listener addresses    p2p.laddr and rpc.laddr bind loopback and are declared on every interface, so a
//	                      full or archive node adopting a sparse file reaches the network where it did
//	                      not. rpc.pprof-laddr is the other direction: a debug listener the node opens on
//	                      a fixed port, declared closed.
//	rate ceilings         p2p.recv-rate and p2p.send-rate cap what one connection may move. The declared
//	                      value is four times what a node runs, so a sparse file raises both.
//	connection policy     p2p.max-connections is ten times higher declared than a seed runs, and
//	                      p2p.allow-duplicate-ip is declared on where a seed has it off.
//	service switches      api.enable, grpc.enable, grpc-web.enable, evm.http_enabled, evm.ws_enabled
//	                      and state-store.ss-enable are open on the node and declared closed for a
//	                      validator and a seed, which serve no queries. A sparse file closes them.
//	retention             pruning is the flag-default row, in every kind: the flag prunes and the
//	                      declaration keeps all state history. min-retain-blocks and
//	                      state-store.ss-keep-recent are the block and state halves of the same choice,
//	                      and each diverges for the one kind whose rule moves it.
//	indexing              tx-index.indexer decides whether the node indexes transactions. The boot's
//	                      writer produces a file for a node that serves queries, so this row is what a
//	                      resolution for a validator states against a file written for something else.
//
// Held as text, because the two sides carry different Go types for the same key often enough that
// comparing values would be comparing shapes. What matters is which keys disagree and what a node runs
// instead.
var divergences = map[registry.Mode]map[string]string{
	registry.ModeValidator: {
		"api.enable":            "true",
		"evm.http_enabled":      "true",
		"evm.ws_enabled":        "true",
		"grpc-web.enable":       "true",
		"grpc.enable":           "true",
		"p2p.recv-rate":         "5120000",
		"p2p.send-rate":         "5120000",
		"pruning":               "default",
		"rpc.pprof-laddr":       "localhost:6060",
		"state-store.ss-enable": "true",
		"tx-index.indexer":      "[kv]",
	},
	registry.ModeFull: {
		"min-retain-blocks": "0",
		"p2p.laddr":         "tcp://127.0.0.1:26656",
		"p2p.recv-rate":     "5120000",
		"p2p.send-rate":     "5120000",
		"pruning":           "default",
		"rpc.laddr":         "tcp://127.0.0.1:26657",
		"rpc.pprof-laddr":   "localhost:6060",
	},
	registry.ModeSeed: {
		"api.enable":             "true",
		"evm.http_enabled":       "true",
		"evm.ws_enabled":         "true",
		"grpc-web.enable":        "true",
		"grpc.enable":            "true",
		"p2p.allow-duplicate-ip": "false",
		"p2p.max-connections":    "100",
		"p2p.recv-rate":          "5120000",
		"p2p.send-rate":          "5120000",
		"pruning":                "default",
		"rpc.pprof-laddr":        "localhost:6060",
		"state-store.ss-enable":  "true",
		"tx-index.indexer":       "[kv]",
	},
	registry.ModeArchive: {
		"p2p.laddr":                  "tcp://127.0.0.1:26656",
		"p2p.recv-rate":              "5120000",
		"p2p.send-rate":              "5120000",
		"pruning":                    "default",
		"rpc.laddr":                  "tcp://127.0.0.1:26657",
		"rpc.pprof-laddr":            "localhost:6060",
		"state-store.ss-keep-recent": "100000",
	},
}

// keysAGeneratedFileLeavesToTheirReader is every declared key a lookup delivers that a boot-generated file
// does not answer.
//
// Each of their readers starts from a default of its own and takes the source's answer only when there is
// one, so what a node runs for one of these keys is that default and the source states nothing. They are
// named rather than compared because the comparison above has nothing to read.
//
// Every one of these declarations is taken from the same default the reader falls back to, so the value a
// node runs is the declared one. That is not measured here. What reaches it is a file stating every
// declared key and a node started from it.
//
// The same in every kind of node. The writer does not vary on the kind, and which keys are declared does
// not either.
var keysAGeneratedFileLeavesToTheirReader = []string{
	"eth_replay.contract_state_checks",
	"evm.enable_test_api",
	"evm.max_concurrent_simulation_calls",
	"evm.max_tx_pool_txs",
	"evm.rpc_stats_interval",
	"genesis.import-file",
	"state-commit.flatkv.enable-read-write-metrics",
	"state-commit.sc-snapshot-writer-limit",
	"state-commit.sc-write-mode-enable-auto",
	"wasm.memory_cache_size",
	"wasm.simulation_gas_limit",
}

// TestTheDivergencesFromGeneratedFilesAreTheRecordedOnes measures what a comment would only claim.
//
// Which keys disagree is measured rather than described, because a key that starts diverging fails and so
// does one that stops. Both deliveries, read where each is read: the keys a decode delivers off the struct
// their file is decoded into, and every other key off the source a lookup reads.
//
// Driven through a real boot with no files of its own and no sei.toml, so nothing is delivered and what
// the node holds is purely what the boot generated.
func TestTheDivergencesFromGeneratedFilesAreTheRecordedOnes(t *testing.T) {
	configtest.Isolate(t)
	ctx := theBootWithNoFileOfItsOwn(t)
	decoded := configmanager.DescribeForTest(t, ctx.Config, keysADecodeDelivers())

	for _, mode := range registry.Modes() {
		t.Run(string(mode), func(t *testing.T) {
			recorded, records := divergences[mode]
			if !records {
				t.Fatalf("nothing records what a %s node diverges on, so this kind is declared and no "+
					"measurement covers it", mode)
			}
			resolved, err := registry.Resolve(mode, registry.Sources{})
			if err != nil {
				t.Fatalf("Resolve: %v", err)
			}

			var measured []string
			for key, declared := range resolved.Values {
				// A key the source does not answer reads as its reader's own default, which the source
				// says nothing about. keysAGeneratedFileLeavesToTheirReader holds that set.
				got, reads := whatTheNodeHolds(key, decoded, ctx)
				if !reads {
					continue
				}
				if fmt.Sprint(declared) == got {
					if _, listed := recorded[key]; listed {
						t.Errorf("%s no longer diverges on a %s node, both sides being %v. Take it off "+
							"the record, so the record stays the set of keys the writers state "+
							"differently", key, mode, declared)
					}
					continue
				}
				measured = append(measured, key)
				want, listed := recorded[key]
				switch {
				case !listed:
					t.Errorf("a %s node is declared to run %s as %v and one that let the boot generate "+
						"its files runs %q, and nothing records that. A sei.toml leaving this key out "+
						"moves the setting", mode, key, declared, got)
				case want != got:
					t.Errorf("a %s node is recorded as running %s as %q and runs %q", mode, key, want, got)
				}
			}

			sort.Strings(measured)
			if len(measured) != len(recorded) {
				t.Errorf("measured %d divergences for a %s node and %d are recorded: %v",
					len(measured), mode, len(recorded), measured)
			}
		})
	}
}

// TestTheKeysAGeneratedFileLeavesToTheirReaderAreTheRecordedOnes holds the set the measurement above skips.
//
// Skipping them is sound only while their reader's default is the declared value, and that holds because
// the declaration is taken from the same default. A key that stops being answered moves into this set and
// nothing else says so, and one that starts being answered leaves it and belongs in the measurement.
func TestTheKeysAGeneratedFileLeavesToTheirReaderAreTheRecordedOnes(t *testing.T) {
	configtest.Isolate(t)
	ctx := theBootWithNoFileOfItsOwn(t)

	decoded := make(map[string]bool)
	for _, key := range keysADecodeDelivers() {
		decoded[key] = true
	}
	recorded := make(map[string]bool, len(keysAGeneratedFileLeavesToTheirReader))
	for _, key := range keysAGeneratedFileLeavesToTheirReader {
		recorded[key] = true
	}

	resolved, err := registry.Resolve(registry.ModeValidator, registry.Sources{})
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}

	var measured []string
	for key := range resolved.Values {
		if decoded[key] || ctx.Viper.Get(key) != nil {
			continue
		}
		measured = append(measured, key)
		if !recorded[key] {
			t.Errorf("%s is declared and a boot-generated file does not answer it, and nothing records "+
				"that. Its reader's own default is what a node runs for it", key)
		}
	}
	for _, key := range keysAGeneratedFileLeavesToTheirReader {
		if answer := ctx.Viper.Get(key); answer != nil {
			t.Errorf("%s is recorded as unanswered and a boot-generated file answers it %v, so what a "+
				"node runs for it is measurable and no measurement covers it", key, answer)
		}
	}

	sort.Strings(measured)
	if len(measured) != len(keysAGeneratedFileLeavesToTheirReader) {
		t.Errorf("measured %d unanswered keys and %d are recorded: %v",
			len(measured), len(keysAGeneratedFileLeavesToTheirReader), measured)
	}
}

// whatTheNodeHolds reads one key off whichever of the two deliveries owns it, and reports whether anything
// answers it.
func whatTheNodeHolds(key string, decoded map[string]string, ctx *server.Context) (string, bool) {
	if held, byADecode := decoded[key]; byADecode {
		return held, true
	}
	answer := ctx.Viper.Get(key)
	if answer == nil {
		return "", false
	}
	return fmt.Sprint(answer), true
}

// theBootWithNoFileOfItsOwn starts a node with no configuration files of its own and no sei.toml, and
// returns what it holds. Nothing is delivered, so both deliveries read purely what the boot generated.
//
// Booted twice, and the second one is returned. The first writes the files, and a flag bound to a key the
// writer sets overwrites that value before anything reads it back, because the file has not been read yet.
// From the second boot the file is read and wins, so what a node runs from its second start onward is what
// the second boot holds, and a divergence only that boot shows would otherwise be invisible here.
func theBootWithNoFileOfItsOwn(t *testing.T) *server.Context {
	t.Helper()
	home := configtest.NewHome(t)
	if err := os.MkdirAll(filepath.Join(home.Root, "config"), 0o750); err != nil {
		t.Fatalf("mkdir: %v", err)
	}

	var ctx *server.Context
	for boot := 0; boot < 2; boot++ {
		cmd := server.StartCmd(nil, home.Root, []trace.TracerProviderOption{})
		if err := cmd.Flags().Set("home", home.Root); err != nil {
			t.Fatalf("set --home: %v", err)
		}
		got, err := runManager(t, configmanager.SeiConfigManager{}, cmd)
		if err != nil {
			t.Fatalf("boot %d was refused: %v", boot+1, err)
		}
		ctx = got
	}
	if ctx.Config == nil {
		t.Fatal("the boot produced no node configuration")
	}
	if ctx.Viper == nil {
		t.Fatal("the boot produced no configuration source")
	}
	return ctx
}
